"""Ed25519 verification: the RFC 8032 test vector, signatures made by OpenSSL 3.5 (`openssl pkeyutl -sign -rawin`), and refusals. Standard library only."""
import sys, unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))
from lattice_scan import ed25519  # noqa: E402

# (public key, message, signature), all hex. The first is RFC 8032 section 7.1 test 1 (empty message); the others were signed with OpenSSL.
VECTORS = [
    ("d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
     "",
     "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b"),
    ("da447deb3b278122b83e1cb84079a63ff30238ec93e2f171f7aabba52824e6bf",
     "6c617474696365",
     "8e9c9b036fafce21597ff04fa18f52383fed6a8464dc2a63c6559b8fb29df59bae6bf9a66895ace9f03f7d656d5d3a8a5ab82cee308cf09e8afba13a74c97506"),
    ("548231c78e5cb92e13511b33e346ca7d229d4300e3038d8cd15923e8d507a7da",
     "",
     "828dcef1efbc6cb4e188a24e02372e9712d2fecd41ac7d5bb9c38360899be7a10940cc795df20f7f4d9ab4a64cd7eb64fe85751a184cda9181ac8a4bacd99300"),
    ("fee4937167420a292b8c1127559bae371f0b8dfb54422a48a169ec9ae167bd86",
     "",
     "14c92c2ed2417b3ad668510b83b98cae45962d4c765ac9ae8331ab7cd2abca52d6990a643ed9c4023e039a38fa35100fca8f9381e21ccae003f4b2f555157002"),
]


class Verify(unittest.TestCase):
    def test_the_rfc_vector_and_openssl_signatures_verify(self):
        for pub, msg, sig in VECTORS:
            self.assertTrue(ed25519.verify(bytes.fromhex(pub), bytes.fromhex(msg), bytes.fromhex(sig)), pub[:12])

    def test_a_changed_message_signature_or_key_is_refused(self):
        pub, msg, sig = (bytes.fromhex(x) for x in VECTORS[1])
        self.assertFalse(ed25519.verify(pub, msg + b"x", sig))
        self.assertFalse(ed25519.verify(pub, b"", sig))
        bad = bytearray(sig); bad[10] ^= 1
        self.assertFalse(ed25519.verify(pub, msg, bytes(bad)))
        bad = bytearray(sig); bad[40] ^= 1
        self.assertFalse(ed25519.verify(pub, msg, bytes(bad)))
        self.assertFalse(ed25519.verify(bytes.fromhex(VECTORS[2][0]), msg, sig))          # another key's signature

    def test_malformed_input_is_false_never_an_exception(self):
        pub, msg, sig = (bytes.fromhex(x) for x in VECTORS[1])
        for p, m, s in ((pub[:31], msg, sig), (pub, msg, sig[:63]), (b"", msg, sig), (pub, msg, b""), (b"\xff" * 32, msg, sig), (pub, msg, b"\xff" * 64), (pub, msg, sig[:32] + b"\xff" * 32)):
            self.assertIs(ed25519.verify(p, m, s), False)

    def test_a_signature_scalar_at_or_above_the_group_order_is_refused(self):
        pub, msg, sig = (bytes.fromhex(x) for x in VECTORS[1])
        s = int.from_bytes(sig[32:], "little") + ed25519._Q                              # the same point, a non-canonical scalar: malleability
        if s < 2**256:
            self.assertFalse(ed25519.verify(pub, msg, sig[:32] + s.to_bytes(32, "little")))


    def test_the_identity_key_with_its_sign_bit_set_is_not_a_key(self):
        """x = 0 with the sign bit set is not a valid encoding (RFC 8032 5.1.3). If it were accepted, anyone could forge a signature for it: R = sB."""
        s = 5
        X, Y, Z, _ = ed25519._mul(s, ed25519._G)
        zi = ed25519._inv(Z)
        r = ((Y * zi % ed25519._P) | (((X * zi) % ed25519._P & 1) << 255)).to_bytes(32, "little")
        forged = r + s.to_bytes(32, "little")
        bad_key = (1).to_bytes(32, "little")[:31] + bytes([0x80])                         # y = 1 (x = 0), sign bit set
        self.assertFalse(ed25519.verify(bad_key, b"any message", forged))

if __name__ == "__main__":
    unittest.main()
